{
  "type": "list",
  "workflows": [
    {
      "name": "convention-review",
      "description": "Review the agent system's conventions by reading source code, docs, and agent configurations. Identify patterns worth codifying, inconsistencies across agents, and gaps in shared knowledge. Output: updated convention docs and actionable findings."
    },
    {
      "name": "growth-cycle",
      "description": "Evidence-based agent improvement. Diagnose a problem (or pick a method to learn), fork agent, apply one change, test via gym, record results. Pass 'learn:<method>' as the task to run in learning mode (always discards)."
    },
    {
      "name": "training-sprint",
      "description": "Batch-run multiple growth experiments efficiently. Diagnose several error patterns in one session, fork and patch each, run gym tests in parallel, then record all results. Use this when Coach has 3+ queued growth targets or wants to rapidly learn multiple methods."
    },
    {
      "name": "verify-setup",
      "description": "Verify coach's tools, workflows, skills, and gym runner. Run this after any changes to coach configuration to confirm everything works."
    },
    {
      "name": "skill-lifecycle",
      "description": "Full skill lifecycle: discover pattern → draft SKILL.md → test in gym → deploy. Each phase is a separate session to prevent skipping steps. Task: describe what kind of pattern to look for. Optional 'agent: <name>' header (default: optimizer)."
    },
    {
      "name": "two-phase",
      "description": "Two-phase workflow enforcement: run analysis in one session, action in another. Phases communicate only through artifacts on disk. Task format: phase1 instructions, then ---, then phase2 instructions. Optional 'agent: <name>' header (default: coder)."
    }
  ]
}

